parameters.jsCode:
const body = $json.body || $json;
const data = body.data || body;

// 1. İsim ve Metin Temizliği
const rawName = (data.name || 'Değerli Müşterimiz').trim();
const cleanName = rawName.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
const rawEmail = (data.email || '').trim().toLowerCase();
const emailValid = rawEmail.includes('@') && rawEmail.includes('.');

// 2. Türk Telefon Numarası Formatlayıcı (+90 5XX XXX XX XX)
let rawPhone = String(data.phone || '').replace(/[^0-9]/g, '');
if (rawPhone.startsWith('90')) rawPhone = rawPhone.slice(2);
if (rawPhone.startsWith('0')) rawPhone = rawPhone.slice(1);
let formattedPhone = rawPhone;
if (rawPhone.length === 10) {
  formattedPhone = `+90 (${rawPhone.slice(0,3)}) ${rawPhone.slice(3,6)} ${rawPhone.slice(6,8)} ${rawPhone.slice(8,10)}`;
} else if (rawPhone.length > 0) {
  formattedPhone = `+90 ${rawPhone}`;
} else {
  formattedPhone = 'Belirtilmedi';
}

// 3. Talep Türü ve Mesajı
const type = data.type || 'quote';
const typeLabelMap = {
  quote: '📋 Yönetim Teklif Talebi',
  callback: '🔔 Hemen Geri Arama',
  contact: '📞 Genel İletişim',
  newsletter: '📧 E-Bülten Üyeliği'
};
const typeLabel = typeLabelMap[type] || '📌 Genel Talep';

// 4. Daire Sayısı ve İlçe Çıkarımı
let daireSayisi = parseInt(data.daireSayisi || data.units || data.meta?.daireSayisi || 0, 10);
if (isNaN(daireSayisi)) daireSayisi = 0;

const rawText = `${data.subject || ''} ${data.message || ''} ${data.meta?.ilce || ''}`.toLowerCase();
const anadoluIlceler = ['kadıköy', 'kadikoy', 'üsküdar', 'uskudar', 'ataşehir', 'atasehir', 'maltepe', 'kartal', 'pendik', 'ümraniye', 'umraniye', 'beykoz', 'çekmeköy', 'cekmekoy', 'sancaktepe', 'sultanbeyli', 'şile', 'sile', 'tuzla'];
const avrupaIlceler = ['beşiktaş', 'besiktas', 'şişli', 'sisli', 'sarıyer', 'sariyer', 'bakırköy', 'bakirkoy', 'beylikdüzü', 'beylikduzu', 'başakşehir', 'basaksehir', 'esenyurt', 'küçükçekmece', 'kucukcekmece', 'büyükçekmece', 'buyukcekmece', 'avcılar', 'avcilar', 'bağcılar', 'bagcilar', 'bahçelievler', 'bahcelievler', 'eyüpsultan', 'eyup', 'fatih', 'gaziosmanpaşa', 'gop', 'güngören', 'gungoren', 'kağıthane', 'kagithane', 'sultangazi', 'zeytinburnu', 'arnavutköy', 'arnavutkoy', 'çatalca', 'catalca', 'silivri'];

let detectedDistrict = 'İstanbul (Genel)';
let region = 'Marmara / İstanbul';
let assignedTeam = 'İstanbul Merkez Operasyon Ekibi';

for (const ilce of anadoluIlceler) {
  if (rawText.includes(ilce)) {
    detectedDistrict = ilce.charAt(0).toUpperCase() + ilce.slice(1);
    region = 'Anadolu Yakası';
    assignedTeam = 'Anadolu Yakası Bölge Yönetimi (Kadıköy/Ataşehir Ofis)';
    break;
  }
}
if (region === 'Marmara / İstanbul') {
  for (const ilce of avrupaIlceler) {
    if (rawText.includes(ilce)) {
      detectedDistrict = ilce.charAt(0).toUpperCase() + ilce.slice(1);
      region = 'Avrupa Yakası';
      assignedTeam = 'Avrupa Yakası Bölge Yönetimi (Beşiktaş/Başakşehir Ofis)';
      break;
    }
  }
}

// 5. Kurumsal Segmentasyon & Öncelik
let segment = 'BUTIK_APARTMAN';
let segmentLabel = '🏢 Butik Apartman (< 30 Bağımsız Bölüm)';
let priority = 'STANDART';

if (daireSayisi >= 150) {
  segment = 'VIP_REZIDANS';
  segmentLabel = '👑 VIP Kurumsal Toplu Yapı & Rezidans (150+ Daire)';
  priority = 'ACIL_VIP';
} else if (daireSayisi >= 30) {
  segment = 'ORTA_OLCEK_SITE';
  segmentLabel = '🏘️ Orta Ölçekli Site (30-150 Daire)';
  priority = 'YUKSEK';
} else if (type === 'quote') {
  priority = 'YUKSEK';
}

return [{
  json: {
    id: 'lead_' + Math.random().toString(36).substr(2, 9) + Date.now().toString(36),
    type,
    typeLabel,
    name: cleanName,
    phone: formattedPhone,
    rawPhone,
    email: emailValid ? rawEmail : null,
    subject: data.subject || `${typeLabel} - ${detectedDistrict}`,
    message: data.message || 'Müşteri web sitesi üzerinden doğrudan form iletti.',
    daireSayisi,
    detectedDistrict,
    region,
    assignedTeam,
    segment,
    segmentLabel,
    priority,
    createdAt: new Date().toISOString(),
    metaJson: JSON.stringify({
      segment,
      priority,
      region,
      assignedTeam,
      daireSayisi,
      district: detectedDistrict,
      source: 'n8n-w01-enterprise-engine',
      userIp: body.headers?.['x-real-ip'] || body.headers?.['x-forwarded-for'] || 'Bilinmiyor'
    })
  }
}];

return [{
  json: {
    status: 'COMPLETED',
    leadId: $json.id,
    name: $json.name,
    district: $json.detectedDistrict,
    segment: $json.segment,
    priority: $json.priority,
    customerEmailSent: Boolean($json.email),
    timestamp: new Date().toISOString()
  }
}];
